function runScript(steps, flags) {
  // Write your solution here
  const ran = [];
  for (const s of steps) {
    ran.push(s.name);
    if (s.exit !== 0 && flags.e) return { ran, exitCode: s.exit };
  }
  return { ran, exitCode: steps.some((s) => s.exit !== 0) ? 1 : 0 };
}

